import json
from fractions import Fraction

# Positive and explicitly negative literals are distinct; absence is not negation.
facts = {
    "badger_has_couch",
    "badger_named_Luna",
    "shark_named_Tango",
    "gadwall_has_blue_card",
    "german_shepherd_on_otter_square",
    "mouse_refuses_stork",
    "stork_watches_2023_movie",
    "stork_in_Ankara",
}

friends = 6 + 1
france_flag_colors = {"blue", "white", "red"}
age_days_lower_bound = Fraction(3 * 365)

# Interpret the factual descriptions and numerical rule antecedents.
if "couch" in {"couch", "chair", "bench"}:
    facts.add("badger_has_seat")
if friends < 6:
    facts.add("gadwall_has_fewer_than_6_friends")
if "blue" in france_flag_colors:
    facts.add("gadwall_card_color_in_France_flag")
if "Luna"[0] == "Tango"[0]:
    facts.add("badger_and_shark_initials_match")
if age_days_lower_bound > 48:
    facts.add("vampire_older_than_48_days")

rules = [
    ("Rule1", ("gadwall_has_fewer_than_6_friends",), "gadwall_builds_plant"),
    ("Rule2", ("stork_in_Canada",), "not_stork_surrenders"),
    ("Rule3", ("not_badger_trades",), "not_mannikin_unites"),
    ("Rule4", ("gadwall_card_color_in_France_flag",), "gadwall_builds_plant"),
    ("Rule5", ("not_gadwall_hugs", "not_mannikin_unites"), "not_pelikan_swears"),
    ("Rule6", ("vampire_older_than_48_days",), "vampire_takes_over"),
    ("Rule7", ("badger_has_seat",), "not_badger_trades"),
    ("Rule8", ("stork_surrenders",), "pelikan_hides_cards"),
    ("Rule9", ("gadwall_creates_castle",), "gadwall_hugs"),
    ("Rule10", ("badger_and_shark_initials_match",), "not_badger_trades"),
    ("Rule11", ("vampire_takes_over",), "not_pelikan_hides_cards"),
    ("Rule12", ("gadwall_builds_plant",), "not_gadwall_hugs"),
    ("Rule13", ("mouse_refuses_stork",), "stork_surrenders"),
]
# Rule9 and Rule12 are instantiated for the gadwall, the relevant creature.
preferred = {("Rule13", "Rule2"), ("Rule8", "Rule11"), ("Rule9", "Rule12")}

def opposite(literal):
    return literal[4:] if literal.startswith("not_") else "not_" + literal

state = frozenset(facts)
seen = set()
settled = False

for _ in range(100):
    if state in seen:
        break
    seen.add(state)
    enabled = [(name, premises, conclusion)
               for name, premises, conclusion in rules
               if all(p in state for p in premises)]
    accepted = [
        rule for rule in enabled
        if not any(
            other[2] == opposite(rule[2])
            and (other[0], rule[0]) in preferred
            for other in enabled
        )
    ]
    next_state = frozenset(facts | {r[2] for r in accepted})
    if next_state == state:
        settled = True
        break
    state = next_state

if not settled:
    print("UNSUPPORTED")
else:
    positive = "pelikan_swears" in state
    negative = "not_pelikan_swears" in state
    if positive and negative:
        print("UNSUPPORTED")
    else:
        answer = "proved" if positive else "disproved" if negative else "unknown"
        supporting_rules = {}
        for name, premises, conclusion in accepted:
            supporting_rules.setdefault(conclusion, []).append((name, premises))

        def proof(literal):
            if literal in facts:
                return {"fact": literal}
            name, premises = supporting_rules[literal][0]
            return {
                "literal": literal,
                "rule": name,
                "from": [proof(p) for p in premises],
            }

        evidence = {
            "friends": friends,
            "blue_in_France_flag": "blue" in france_flag_colors,
            "positive_query_derived": positive,
            "negative_query_derived": negative,
        }
        if positive or negative:
            evidence["proof"] = proof(
                "pelikan_swears" if positive else "not_pelikan_swears"
            )
        print(json.dumps(
            {"final_answer": answer, "evidence": evidence},
            separators=(",", ":")
        ))
